16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.time.Month;
26	import java.time.Period;
27	import java.util.*;
28	
29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    /**
41	     * The fixed list of public holidays that a registration date must roll forward past, in addition
42	     * to weekends.
43	     */
44	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
45	        LocalDate.of(2026, 1, 1),
46	        LocalDate.of(2026, 1, 26),
47	        LocalDate.of(2026, 4, 25),
48	        LocalDate.of(2026, 12, 25),
49	        LocalDate.of(2026, 12, 28));
50	
51	    @Column(name = "title")
52	    private String title;
53	
54	    @Column(name = "address")
55	    @NotEmpty
56	    private String address;
57	
58	    @Column(name = "address_line1")
59	    private String addressLine1;
60	
61	    @Column(name = "address_line2")
62	    private String addressLine2;
63	
64	    @Column(name = "city")
65	    @NotEmpty
66	    private String city;
67	
68	    @Column(name = "telephone")
69	    @NotEmpty
70	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (+ followed by 8 to 15 digits)")
71	    private String telephone;
72	
73	    @Column(name = "email")
74	    private String email;
75	
76	    @Column(name = "postcode")
77	    private String postcode;
78	
79	    @Column(name = "registration_date", columnDefinition = "DATE")
80	    private LocalDate registrationDate;
81	
82	    @Column(name = "birth_date", columnDefinition = "DATE")
83	    private LocalDate birthDate;
84	
85	    @Column(name = "customer_code")
86	    private String customerCode;
87	
88	    @Column(name = "household_id")
89	    private String householdId;
90	
91	    @Column(name = "namesake_count")
92	    private Integer namesakeCount;
93	
94	    @Column(name = "possible_duplicate")
95	    private Boolean possibleDuplicate;
96	
97	    @Column(name = "possible_duplicate_of")
98	    private Integer possibleDuplicateOf;
99	
100	    @Column(name = "membership_level_cap")
101	    private Integer membershipLevelCap;
102	
103	    @Column(name = "deleted")
104	    private boolean deleted;
105	
106	    @Transient
107	    private Integer householdSize;
108	
109	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
110	    private Set<Pet> pets;
111	
112	    public String getTitle() {
113	        return this.title;
114	    }
115	
116	    public void setTitle(String title) {
117	        this.title = title;
118	    }
119	
120	    /**
121	     * Derives the owner's salutation for the read-only {@code salutation} field: the title, a single
122	     * space and the lastName when a title is present (e.g. {@code 'DR Who'}), or just the lastName
123	     * when no title was supplied.
124	     */
125	    @Transient
126	    public String getSalutation() {
127	        if (this.title == null || this.title.isBlank()) {
128	            return getLastName();
129	        }
130	        return this.title + " " + getLastName();
131	    }
132	
133	    public String getAddress() {
134	        return this.address;
135	    }
136	
137	    public void setAddress(String address) {
138	        this.address = address;
139	    }
140	
141	    public String getAddressLine1() {
142	        return this.addressLine1;
143	    }
144	
145	    public void setAddressLine1(String addressLine1) {
146	        this.addressLine1 = addressLine1;
147	    }
148	
149	    public String getAddressLine2() {
150	        return this.addressLine2;
151	    }
152	
153	    public void setAddressLine2(String addressLine2) {
154	        this.addressLine2 = addressLine2;
155	    }
156	
157	    public String getCity() {
158	        return this.city;
159	    }
160	
161	    public void setCity(String city) {
162	        this.city = city;
163	    }
164	
165	    public String getTelephone() {
166	        return this.telephone;
167	    }
168	
169	    public void setTelephone(String telephone) {
170	        this.telephone = telephone;
171	    }
172	
173	    public String getEmail() {
174	        return this.email;
175	    }
176	
177	    public void setEmail(String email) {
178	        this.email = email == null ? null : email.toLowerCase();
179	    }
180	
181	    public String getPostcode() {
182	        return this.postcode;
183	    }
184	
185	    public void setPostcode(String postcode) {
186	        this.postcode = postcode;
187	    }
188	
189	    public LocalDate getRegistrationDate() {
190	        return this.registrationDate;
191	    }
192	
193	    public void setRegistrationDate(LocalDate registrationDate) {
194	        this.registrationDate = registrationDate;
195	    }
196	
197	    public LocalDate getBirthDate() {
198	        return this.birthDate;
199	    }
200	
201	    public void setBirthDate(LocalDate birthDate) {
202	        this.birthDate = birthDate;
203	    }
204	
205	    /**
206	     * Derives the owner's age band from the birth date, measured against the registration date:
207	     * {@code 'MINOR'} when under 18, {@code 'ADULT'} for 18 to 64 inclusive, and {@code 'SENIOR'}
208	     * from 65 on. Returns {@code null} when either the birth date or the registration date is absent,
209	     * so an owner created without a birth date has no age band.
210	     */
211	    @Transient
212	    public String getAgeBand() {
213	        if (this.birthDate == null || this.registrationDate == null) {
214	            return null;
215	        }
216	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
217	        if (age < 18) {
218	            return "MINOR";
219	        }
220	        return age < 65 ? "ADULT" : "SENIOR";
221	    }
222	
223	    public String getCustomerCode() {
224	        return this.customerCode;
225	    }
226	
227	    public void setCustomerCode(String customerCode) {
228	        this.customerCode = customerCode;
229	    }
230	
231	    public String getHouseholdId() {
232	        return this.householdId;
233	    }
234	
235	    public void setHouseholdId(String householdId) {
236	        this.householdId = householdId;
237	    }
238	
239	    public Integer getNamesakeCount() {
240	        return this.namesakeCount;
241	    }
242	
243	    public void setNamesakeCount(Integer namesakeCount) {
244	        this.namesakeCount = namesakeCount;
245	    }
246	
247	    /**
248	     * The number of owners belonging to this owner's household (owners sharing this owner's
249	     * household id, including this owner). Not persisted: it is a live count populated at read
250	     * time and feeds the {@code membershipPoints} calculation. Null when it has not been resolved.
251	     */
252	    public Integer getHouseholdSize() {
253	        return this.householdSize;
254	    }
255	
256	    public void setHouseholdSize(Integer householdSize) {
257	        this.householdSize = householdSize;
258	    }
259	
260	    /**
261	     * Whether this owner was flagged a possible (soft-match) duplicate at creation: it was not a
262	     * hard duplicate, yet it shared an existing owner's lastName and postcode while carrying a
263	     * different telephone. False when no such match existed.
264	     */
265	    public Boolean getPossibleDuplicate() {
266	        return this.possibleDuplicate;
267	    }
268	
269	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
270	        this.possibleDuplicate = possibleDuplicate;
271	    }
272	
273	    /**
274	     * The id of the existing owner this owner soft-matches (same lastName and postcode, different
275	     * telephone), or {@code null} when it is not a possible duplicate.
276	     */
277	    public Integer getPossibleDuplicateOf() {
278	        return this.possibleDuplicateOf;
279	    }
280	
281	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
282	        this.possibleDuplicateOf = possibleDuplicateOf;
283	    }
284	
285	    /**
286	     * The ceiling applied to this owner's derived {@code membershipLevel}, fixed when the owner was
287	     * created: one above the maximum membershipLevel among the household members that already existed
288	     * at that time. The reported membership level is never allowed to exceed this cap. {@code null}
289	     * when the owner had no existing household member at creation, in which case no cap applies.
290	     */
291	    public Integer getMembershipLevelCap() {
292	        return this.membershipLevelCap;
293	    }
294	
295	    public void setMembershipLevelCap(Integer membershipLevelCap) {
296	        this.membershipLevelCap = membershipLevelCap;
297	    }
298	
299	    /**
300	     * Computes this owner's membership points for the given household size. Points start at 0 and
301	     * accumulate: 2 when an email address is present, 1 when the owner had no namesakes at creation
302	     * (namesakeCount is 0), 2 for a household of 3 or more members, and 3 for tenure of one or more
303	     * elapsed fiscal years (the number of 1-July fiscal-year boundaries between the registration date
304	     * and the current date). The household size is supplied by the caller (it is a live, non-persisted
305	     * count), so a {@code null} size contributes no household points.
306	     */
307	    public int membershipPoints(Integer householdSize) {
308	        int points = 0;
309	        if (this.email != null && !this.email.isBlank()) {
310	            points += 2;
311	        }
312	        if (this.namesakeCount != null && this.namesakeCount == 0) {
313	            points += 1;
314	        }
315	        if (householdSize != null && householdSize >= 3) {
316	            points += 2;
317	        }
318	        if (this.registrationDate != null
319	            && fiscalYear(LocalDate.now()) - fiscalYear(this.registrationDate) >= 1) {
320	            points += 3;
321	        }
322	        return points;
323	    }
324	
325	    /**
326	     * Derives this owner's numeric membership level for the given household size from its membership
327	     * points: 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points. The
328	     * result is then capped at {@link #getMembershipLevelCap()} (the ceiling fixed at creation from
329	     * the household this owner joined): when a cap is present the level can never exceed it. No cap is
330	     * applied when the owner had no existing household member at creation.
331	     */
332	    public int membershipLevel(Integer householdSize) {
333	        int points = membershipPoints(householdSize);
334	        int level;
335	        if (points <= 1) {
336	            level = 1;
337	        }
338	        else if (points <= 3) {
339	            level = 2;
340	        }
341	        else if (points <= 5) {
342	            level = 3;
343	        }
344	        else {
345	            level = 4;
346	        }
347	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
348	            level = this.membershipLevelCap;
349	        }
350	        return level;
351	    }
352	
353	    /**
354	     * Whether this owner has been soft-deleted. A newly created owner is not deleted; a
355	     * {@code DELETE /api/owners/{id}} flags it deleted while retaining the row. Deleted owners are
356	     * ignored by the create endpoint's duplicate and identity checks.
357	     */
358	    public boolean isDeleted() {
359	        return this.deleted;
360	    }
361	
362	    public void setDeleted(boolean deleted) {
363	        this.deleted = deleted;
364	    }
365	
366	    /**
367	     * The owner's derived identity key, used as the single basis for duplicate detection:
368	     * the normalized telephone, the email (empty when absent) and the household id (empty
369	     * when absent), joined with {@code '|'}. Two owners are duplicates only when their whole
370	     * identity keys are equal, so any single differing component (telephone, email or
371	     * household) yields distinct keys and is allowed. Derived from persisted fields, so it is
372	     * not itself a persistent column.
373	     */
374	    @Transient
375	    public String getIdentityKey() {
376	        return (this.telephone == null ? "" : this.telephone)
377	            + "|" + (this.email == null ? "" : this.email)
378	            + "|" + (this.householdId == null ? "" : this.householdId);
379	    }
380	
381	    /**
382	     * Establishes the effective registration date at persist time, so the create-time default
383	     * applies to any persistence path.
384	     */
385	    @PrePersist
386	    protected void defaultRegistrationDate() {
387	        resolveRegistrationDate();
388	    }
389	
390	    /**
391	     * Resolves this owner's effective registration date and stores it: the supplied value is used, or
392	     * the server's current date when none was supplied, and the result is rolled forward onto a
393	     * business day (a Saturday, Sunday or public holiday rolls forward to the next business day).
394	     * Returns the resolved date.
395	     * Idempotent, so it is safe to call from both the create flow and the persist hook.
396	     */
397	    public LocalDate resolveRegistrationDate() {
398	        LocalDate effective = this.registrationDate == null ? LocalDate.now() : this.registrationDate;
399	        this.registrationDate = toBusinessDay(effective);
400	        return this.registrationDate;
401	    }
402	
403	    /**
404	     * Derives the fiscal year that a date falls in, where each fiscal year starts on 1 July and is
405	     * identified by the calendar year in which it ends: a date from July onwards belongs to the
406	     * fiscal year ending in the following calendar year (e.g. 2 July 2026 gives 2027), while a date
407	     * from January to June belongs to the fiscal year ending in its own calendar year. Returns
408	     * {@code null} when the date is absent.
409	     */
410	    public static Integer fiscalYear(LocalDate date) {
411	        if (date == null) {
412	            return null;
413	        }
414	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
415	    }
416	
417	    /**
418	     * Rolls a registration date forward onto a business day: a Saturday, Sunday or listed public
419	     * holiday is advanced to the next non-holiday weekday, while any other weekday (and {@code null})
420	     * is returned unchanged. Applying this to a date that is already a business day is a no-op, so it
421	     * is safe to call more than once.
422	     */
423	    public static LocalDate toBusinessDay(LocalDate date) {
424	        if (date == null) {
425	            return null;
426	        }
427	        LocalDate result = date;
428	        while (isWeekend(result) || PUBLIC_HOLIDAYS.contains(result)) {
429	            result = result.plusDays(1);
430	        }
431	        return result;
432	    }
433	
434	    private static boolean isWeekend(LocalDate date) {
435	        return switch (date.getDayOfWeek()) {
436	            case SATURDAY, SUNDAY -> true;
437	            default -> false;
438	        };
439	    }
440	
441	    protected Set<Pet> getPetsInternal() {
442	        if (this.pets == null) {
443	            this.pets = new HashSet<>();
444	        }
445	        return this.pets;
446	    }
447	
448	    protected void setPetsInternal(Set<Pet> pets) {
449	        this.pets = pets;
450	    }
451	
452	    public List<Pet> getPets() {
453	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
454	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
455	        return Collections.unmodifiableList(sortedPets);
456	    }
457	
458	    public void setPets(List<Pet> pets) {
459	        this.pets = new HashSet<>(pets);
460	    }
461	
462	    public void addPet(Pet pet) {
463	        getPetsInternal().add(pet);
464	        pet.setOwner(this);
465	    }
466	
467	    /**
468	     * Return the Pet with the given name, or null if none found for this Owner.
469	     *
470	     * @param name to test
471	     * @return true if pet name is already in use
472	     */
473	    public Pet getPet(String name) {
474	        return getPet(name, false);
475	    }
476	
477	    /**
478	     * Return the Pet with the given name, or null if none found for this Owner.
479	     *
480	     * @param name to test
481	     * @return true if pet name is already in use
482	     */
483	    public Pet getPet(String name, boolean ignoreNew) {
484	        name = name.toLowerCase();
485	        for (Pet pet : getPetsInternal()) {
486	            if (!ignoreNew || !pet.isNew()) {
487	                String compName = pet.getName();
488	                compName = compName.toLowerCase();
489	                if (compName.equals(name)) {
490	                    return pet;
491	                }
492	            }
493	        }
494	        return null;
495	    }
496	
497	    public Pet getPet(Integer petId) {
498	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
499	    }
500	
501	    @Override
502	    public String toString() {
503	        return new ToStringCreator(this)
504	
505	            .append("id", this.getId())
506	            .append("new", this.isNew())
507	            .append("lastName", this.getLastName())
