390	    /**
391	     * Resolves this owner's effective registration date and stores it: the supplied value is used, or
392	     * the server's current date when none was supplied, and the result is rolled forward onto a
393	     * business day (a Saturday, Sunday or public holiday rolls forward to the next business day).
394	     * Returns the resolved date.
395	     * Idempotent, so it is safe to call from both the create flow and the persist hook.
396	     */
397	    public LocalDate resolveRegistrationDate() {
398	        LocalDate effective = this.registrationDate == null ? LocalDate.now() : this.registrationDate;
399	        this.registrationDate = toBusinessDay(effective);
400	        return this.registrationDate;
401	    }
402	
403	    /**
404	     * Derives the fiscal year that a date falls in, where each fiscal year starts on 1 July and is
405	     * identified by the calendar year in which it ends: a date from July onwards belongs to the
406	     * fiscal year ending in the following calendar year (e.g. 2 July 2026 gives 2027), while a date
407	     * from January to June belongs to the fiscal year ending in its own calendar year. Returns
408	     * {@code null} when the date is absent.
409	     */
410	    public static Integer fiscalYear(LocalDate date) {
411	        if (date == null) {
412	            return null;
413	        }
414	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
415	    }
416	
417	    /**
418	     * Rolls a registration date forward onto a business day: a Saturday, Sunday or listed public
419	     * holiday is advanced to the next non-holiday weekday, while any other weekday (and {@code null})
420	     * is returned unchanged. Applying this to a date that is already a business day is a no-op, so it
421	     * is safe to call more than once.
422	     */
423	    public static LocalDate toBusinessDay(LocalDate date) {
424	        if (date == null) {
425	            return null;
426	        }
427	        LocalDate result = date;
428	        while (isWeekend(result) || PUBLIC_HOLIDAYS.contains(result)) {
429	            result = result.plusDays(1);
430	        }
431	        return result;
432	    }
433	
434	    private static boolean isWeekend(LocalDate date) {
435	        return switch (date.getDayOfWeek()) {
436	            case SATURDAY, SUNDAY -> true;
437	            default -> false;
438	        };
439	    }
