453	    /**
454	     * Whether any existing owner already belongs to the household identified by the given
455	     * (deterministic) household id. This is the single basis for the household-duplicate rule:
456	     * owners that share a last name and postcode share a household id, so a matching existing owner
457	     * means the new owner is a household duplicate. Returns {@code false} when the id is absent.
458	     */
459	    @Override
460	    @Transactional(readOnly = true)
461	    public boolean existsOwnerInHousehold(String householdId) throws DataAccessException {
462	        if (householdId == null || householdId.isBlank()) {
463	            return false;
464	        }
465	        return ownerRepository.findAll().stream()
466	            .filter(existing -> !existing.isDeleted())
467	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
468	    }
