470	    /**
471	     * Counts the owners that belong to the household identified by the given (deterministic)
472	     * household id, i.e. the number of owners currently sharing it. Used to size a household for
473	     * the membership-points calculation. Returns {@code 0} when the id is absent.
474	     */
475	    @Override
476	    @Transactional(readOnly = true)
477	    public int countOwnersByHouseholdId(String householdId) throws DataAccessException {
478	        if (householdId == null || householdId.isBlank()) {
479	            return 0;
480	        }
481	        return (int) ownerRepository.findAll().stream()
482	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
