486	    /**
487	     * Returns the existing, non-deleted owners that belong to the household identified by the given
488	     * (deterministic) household id, i.e. the current members of that household. Used to derive the
489	     * membership-level ceiling a new owner joining the household is subject to. Returns an empty
490	     * collection when the id is absent.
491	     */
492	    @Override
493	    @Transactional(readOnly = true)
494	    public Collection<Owner> findOwnersByHouseholdId(String householdId) throws DataAccessException {
495	        if (householdId == null || householdId.isBlank()) {
496	            return List.of();
497	        }
498	        return ownerRepository.findAll().stream()
499	            .filter(existing -> !existing.isDeleted())
500	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
501	            .toList();
502	    }
503	
504	    /**
505	     * Computes the membership-level ceiling for a new owner joining the household identified by the
506	     * given (deterministic) household id: one above the current maximum membershipLevel among the
507	     * existing (non-deleted) household members. The members' live household size is passed explicitly
508	     * to {@link Owner#membershipLevel(Integer)}, so no persistent state is mutated. Returns
509	     * {@code null} when the household has no existing member, so no cap applies to the new owner.
510	     */
511	    @Override
512	    @Transactional(readOnly = true)
513	    public Integer computeMembershipLevelCap(String householdId) throws DataAccessException {
514	        Collection<Owner> members = findOwnersByHouseholdId(householdId);
515	        if (members.isEmpty()) {
516	            return null;
517	        }
518	        int maxLevel = 0;
519	        for (Owner member : members) {
520	            int level = member.membershipLevel(members.size());
521	            if (level > maxLevel) {
522	                maxLevel = level;
523	            }
524	        }
525	        return maxLevel + 1;
526	    }
527	
528	    /**
529	     * Normalizes a household-identity field for comparison by trimming, collapsing internal
530	     * runs of whitespace to a single space and lower-casing, so values that differ only in
531	     * whitespace or letter case are treated as equal.
532	     */
533	    private static String normalizeHouseholdField(String value) {
534	        if (value == null) {
535	            return null;
536	        }
537	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
538	    }
539	
540	    /**
541	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
542	     * UTF-8 bytes of {@code seed}.
543	     */
544	    private static String sha256UpperHex(String seed, int length) {
545	        try {
546	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
547	            byte[] hash = digest.digest(seed.getBytes(StandardCharsets.UTF_8));
548	            StringBuilder sb = new StringBuilder(hash.length * 2);
549	            for (byte b : hash) {
550	                sb.append(String.format("%02X", b));
551	            }
552	            return sb.substring(0, length);
553	        }
554	        catch (NoSuchAlgorithmException e) {
555	            throw new IllegalStateException("SHA-256 not available", e);
556	        }
557	    }
