116	    /**
117	     * Whether more than 80 owners have already been created on {@code registrationDate},
118	     * signalling a bulk-signup surge for the read-only {@code bulkSignupWarning} field.
119	     */
120	    private boolean isBulkSignup(LocalDate registrationDate) {
121	        return this.clinicService.countOwnersByRegistrationDate(registrationDate) > 80;
122	    }
