124	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
125	    @Override
126	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
127	        // Idempotent replay: a repeat with an already-seen key returns the originally created
128	        // owner with 200 rather than creating (and possibly rejecting as) a duplicate.
129	        Integer existingId = this.clinicService.findOwnerIdByIdempotencyKey(idempotencyKey);
130	        if (existingId != null) {
131	            Owner existing = this.clinicService.findOwnerById(existingId);
132	            if (existing != null) {
133	                return new ResponseEntity<>(toOwnerDtoWithDerived(existing), HttpStatus.OK);
134	            }
135	        }
136	        HttpHeaders headers = new HttpHeaders();
137	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
138	        LocalDate registrationDate = owner.resolveRegistrationDate();
139	        if (this.clinicService.countOwnersByRegistrationDate(registrationDate) >= 100) {
140	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
141	        }
142	        if (this.clinicService.countOwnersByCity(owner.getCity()) >= 50) {
143	            return new ResponseEntity<>(HttpStatus.CONFLICT);
144	        }
145	        // The household id is deterministic: owners that share a (normalized lastName, postcode)
146	        // share it automatically. It feeds the identity key, the membership-level cap and the
147	        // possible-duplicate suppression below.
148	        owner.setHouseholdId(this.clinicService.computeHouseholdId(owner));
149	        boolean householdExists = this.clinicService.existsOwnerInHousehold(owner.getHouseholdId());
150	        // A new owner joining an existing household (owners sharing a normalized lastName and
151	        // postcode) has its membershipLevel capped at one above the current maximum membershipLevel
152	        // among the existing household members. With no existing household member, no cap applies.
153	        owner.setMembershipLevelCap(this.clinicService.computeMembershipLevelCap(owner.getHouseholdId()));
154	        // Hard duplicate detection is consolidated into the owner's derived identity key (see
155	        // Owner#getIdentityKey): reject only when the new owner's whole key matches an existing one.
156	        if (this.clinicService.existsOwnerWithIdentityKey(owner.getIdentityKey())) {
157	            return new ResponseEntity<>(HttpStatus.CONFLICT);
158	        }
159	        // Soft-match: shares an existing owner's lastName and postcode with a different telephone,
160	        // flagged 'possibleDuplicate'. A declared household member is not a suspected duplicate, so
161	        // the flag is suppressed when this owner joins an existing household.
162	        Integer possibleDuplicateOf = householdExists ? null
163	            : this.clinicService.findPossibleDuplicateOwnerId(owner);
164	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
165	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
166	        owner.setNamesakeCount(
167	            this.clinicService.countOwnersByName(owner.getFirstName(), owner.getLastName()));
168	        this.clinicService.saveOwner(owner);
169	        this.clinicService.registerIdempotencyKey(idempotencyKey, owner.getId());
170	        OwnerDto ownerDto = toOwnerDtoWithDerived(owner);
171	        auditLogger.info(
172	            "owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
173	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
174	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
175	        headers.setLocation(UriComponentsBuilder.newInstance()
176	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
177	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
178	    }
