156	        if (this.clinicService.existsOwnerWithIdentityKey(owner.getIdentityKey())) {
157	            return new ResponseEntity<>(HttpStatus.CONFLICT);
158	        }
159	        // Soft-match: shares an existing owner's lastName and postcode with a different telephone,
160	        // flagged 'possibleDuplicate'. A declared household member is not a suspected duplicate, so
161	        // the flag is suppressed when this owner joins an existing household.
162	        Integer possibleDuplicateOf = householdExists ? null
163	            : this.clinicService.findPossibleDuplicateOwnerId(owner);
164	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
165	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
166	        owner.setNamesakeCount(
167	            this.clinicService.countOwnersByName(owner.getFirstName(), owner.getLastName()));
168	        this.clinicService.saveOwner(owner);
169	        this.clinicService.registerIdempotencyKey(idempotencyKey, owner.getId());
170	        OwnerDto ownerDto = toOwnerDtoWithDerived(owner);
171	        auditLogger.info(
172	            "owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
173	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
174	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
175	        headers.setLocation(UriComponentsBuilder.newInstance()
176	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
177	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
178	    }
