3	import jakarta.validation.ConstraintValidator;
4	import jakarta.validation.ConstraintValidatorContext;
5	
6	import java.util.Locale;
7	import java.util.Set;
8	
9	public class EmailDomainValidator implements ConstraintValidator<EmailDomainValidation, String> {
10	
11	    private static final Set<String> BLOCKED_DOMAINS =
12	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
13	
14	    @Override
15	    public boolean isValid(String email, ConstraintValidatorContext context) {
16	        // absence and general syntax are handled elsewhere (@NotEmpty / format: email);
17	        // here we only reject disposable-email domains.
18	        if (email == null || email.isBlank()) {
19	            return true;
20	        }
21	        int at = email.lastIndexOf('@');
22	        if (at < 0 || at == email.length() - 1) {
23	            return true;
24	        }
25	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
26	        return !BLOCKED_DOMAINS.contains(domain);
27	    }
28	}
