public class SoundexCheck {
    static char soundexDigit(char c) {
        return switch (c) {
            case 'B','F','P','V' -> '1';
            case 'C','G','J','K','Q','S','X','Z' -> '2';
            case 'D','T' -> '3';
            case 'L' -> '4';
            case 'M','N' -> '5';
            case 'R' -> '6';
            default -> '0';
        };
    }
    static String soundex(String value) {
        if (value == null) return "";
        String letters = value.toUpperCase().replaceAll("[^A-Z]", "");
        if (letters.isEmpty()) return "";
        StringBuilder code = new StringBuilder();
        code.append(letters.charAt(0));
        char previous = soundexDigit(letters.charAt(0));
        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
            char c = letters.charAt(i);
            if (c=='H'||c=='W') continue;
            char digit = soundexDigit(c);
            if (digit != '0' && digit != previous) code.append(digit);
            previous = digit;
        }
        while (code.length() < 4) code.append('0');
        return code.toString();
    }
    public static void main(String[] a) {
        String[][] cases = {
            {"Robert","R163"},{"Rupert","R163"},{"Rubin","R150"},
            {"Ashcraft","A261"},{"Ashcroft","A261"},{"Tymczak","T522"},
            {"Pfister","P236"},{"Honeyman","H555"}
        };
        boolean ok=true;
        for (String[] c: cases){ String got=soundex(c[0]); boolean p=got.equals(c[1]); ok&=p; System.out.println(c[0]+" -> "+got+" expected "+c[1]+(p?" OK":" FAIL")); }
        System.out.println(ok?"ALL OK":"SOME FAIL");
    }
}
